@startuml

class Aircraft {
  + Model : string
  + Price : double
}

class Contract {
  + GlobalContractId : string
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + AircraftModel : string
  + NegotiatedPrice : double
  + Options : string
  + Customizations : string
  + DeliveryDate : date
}

class Salesperson {
  + Name : string
  + StartDate : date
}

class Airline {
  + Name : string
  + ParentAirline : Airline
}

Aircraft "1" -- "0..*" Acquisition
Contract "1" -- "0..*" Acquisition
Salesperson "0..*" -- "0..*" Contract
Airline "0..1" -- "0..*" Airline

@enduml

